.chapter-scope {
  --ink: #1a2b4a;
  --muted: #5d6d7e;
  --accent: #007acc;
  --warm: #d4ac6e;
  --line: #e0e0e0;
  --paper: #f9f9f7;

  font-family: 'Source Serif Pro', Georgia, serif;
  color: var(--ink);
  background: var(--paper);
  padding: 2rem;
  max-width: 1200px;
  margin: 0 auto;
  line-height: 1.6;
}

.chapter-scope h1 {
  font-size: 2.5rem;
  margin-bottom: 0.5rem;
  border-bottom: 2px solid var(--ink);
  padding-bottom: 1rem;
}

.chapter-scope .lead {
  font-size: 1.2rem;
  color: var(--muted);
  margin-bottom: 2rem;
}

.chapter-scope h2 {
  font-size: 1.8rem;
  margin-top: 2rem;
  color: var(--ink);
}

.chapter-scope h3 {
  font-size: 1.4rem;
  margin-top: 1.5rem;
  color: var(--ink);
}

.content-grid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 2rem;
  margin-bottom: 3rem;
}

.main-flow p {
  font-size: 1.1rem;
  margin-bottom: 1rem;
  text-align: justify;
}

.formula-block {
  background: #fff;
  border-left: 4px solid var(--accent);
  padding: 1.5rem;
  margin: 1.5rem 0;
  box-shadow: 0 2px 5px rgba(0,0,0,0.05);
}

.formula-block .label {
  display: block;
  font-size: 0.9rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 0.5rem;
}

.formula-block .caption {
  font-size: 0.95rem;
  color: var(--muted);
  margin-top: 1rem;
  font-style: italic;
}

.sidebar-flow {
  background: #fff;
  padding: 1.5rem;
  border: 1px solid var(--line);
  border-radius: 4px;
}

.viz-container svg {
  width: 100%;
  height: auto;
  display: block;
}

.source-btn {
  background: transparent;
  border: 1px solid var(--muted);
  color: var(--muted);
  padding: 0.4rem 0.8rem;
  font-size: 0.9rem;
  cursor: pointer;
  margin-right: 0.5rem;
  transition: all 0.2s;
}

.source-btn:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.interaction-zone {
  background: #fff;
  border: 1px solid var(--line);
  padding: 2rem;
  margin-top: 3rem;
  border-radius: 4px;
}

.canvas-wrapper {
  position: relative;
  width: 100%;
  max-width: 600px;
  margin: 0 auto 2rem;
  background: #f0f4f8;
  border-radius: 4px;
  overflow: hidden;
}

#capacity-canvas {
  display: block;
  width: 100%;
  height: auto;
  cursor: grab;
}

#capacity-canvas:active {
  cursor: grabbing;
}

.canvas-controls {
  padding: 1.5rem;
  background: #fff;
  border-top: 1px solid var(--line);
}

.canvas-controls label {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1rem;
  font-size: 0.95rem;
  color: var(--ink);
}

.canvas-controls input[type="range"] {
  width: 60%;
  accent-color: var(--accent);
}

.readout {
  margin-top: 1rem;
  padding: 0.8rem;
  background: var(--ink);
  color: #fff;
  border-radius: 4px;
  text-align: center;
  font-weight: bold;
}

#btn-reset {
  display: block;
  width: 100%;
  margin-top: 1rem;
  padding: 0.8rem;
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  font-size: 1rem;
}

#btn-reset:hover {
  background: #005a9e;
}

.analysis-panel {
  margin-top: 2rem;
  padding-top: 1.5rem;
  border-top: 1px dashed var(--line);
}

.analysis-panel ul {
  list-style: none;
  padding-left: 0;
}

.analysis-panel li {
  margin-bottom: 0.5rem;
  font-size: 1rem;
}

.note {
  font-size: 0.85rem;
  color: var(--muted);
  margin-top: 1rem;
  font-style: italic;
}

@media (max-width: 768px) {
  .content-grid {
    grid-template-columns: 1fr;
  }
  .chapter-scope {
    padding: 1rem;
  }
}
