javascript:
(function() {
  const canvas = document.getElementById('capacity-canvas');
  const ctx = canvas.getContext('2d');
  const inputW = document.getElementById('input-w');
  const inputSNR = document.getElementById('input-snr');
  const valW = document.getElementById('val-w');
  const valSNR = document.getElementById('val-snr');
  const valC = document.getElementById('val-c');
  const gainW = document.getElementById('gain-w');
  const gainP = document.getElementById('gain-p');
  const btnReset = document.getElementById('btn-reset');

  let rotationX = 0.5;
  let rotationY = 0.5;
  let isDragging = false;
  let lastMouseX = 0;
  let lastMouseY = 0;

  // 教学参数：网格分辨率
  const gridSize = 20;

  function calculateCapacity(w, snr) {
    return w * Math.log2(1 + snr);
  }

  function drawSurface() {
    const w = parseInt(inputW.value);
    const snr = parseInt(inputSNR.value);
    const c = calculateCapacity(w, snr);

    // 更新数值显示
    valW.textContent = w;
    valSNR.textContent = snr;
    valC.textContent = (c / 1000).toFixed(2);
    valC.setAttribute('data-value', c);

    // 计算边际增益 (导数近似)
    // dC/dW = log2(1+SNR)
    const dC_dW = Math.log2(1 + snr);
    const percentGainW = ((dC_dW * (w * 0.1)) / c) * 100;

    // dC/dSNR = W / ((1+SNR) * ln(2))
    const dC_dSNR = w / ((1 + snr) * Math.LN2);
    const percentGainP = ((dC_dSNR * (snr * 0.1)) / c) * 100;

    gainW.textContent = percentGainW.toFixed(1);
    gainW.setAttribute('data-value', percentGainW);
    gainP.textContent = percentGainP.toFixed(1);
    gainP.setAttribute('data-value', percentGainP);

    // 清空画布
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const width = canvas.width;
    const height = canvas.height;
    const centerX = width / 2;
    const centerY = height / 2 + 50;

    // 投影参数
    const scale = 0.8;
    const fov = 400;

    // 绘制网格线
    ctx.strokeStyle = '#1a2b4a';
    ctx.lineWidth = 1;
    ctx.beginPath();

    const points = [];

    // 生成曲面点
    for (let i = 0; i <= gridSize; i++) {
      const row = [];
      for (let j = 0; j <= gridSize; j++) {
        // 归一化坐标 0..1
        const u = i / gridSize;
        const v = j / gridSize;

        // 映射到实际范围 (W: 0-5000, SNR: 0-100)
        const xVal = u * 5000;
        const yVal = v * 100;
        const zVal = calculateCapacity(xVal, yVal) / 50; // 缩放 Z 轴以便观察

        // 3D 旋转
        const x = xVal - 2500;
        const y = yVal - 50;
        const z = zVal;

        const cosX = Math.cos(rotationX);
        const sinX = Math.sin(rotationX);
        const cosY = Math.cos(rotationY);
        const sinY = Math.sin(rotationY);

        // 绕 Y 轴旋转
        const x1 = x * cosY - z * sinY;
        const z1 = z * cosY + x * sinY;

        // 绕 X 轴旋转
        const y2 = y * cosX - z1 * sinX;
        const z2 = z1 * cosX + y * sinX;

        // 透视投影
        const perspective = fov / (fov + z2 + 200);
        const px = centerX + x1 * perspective * scale;
        const py = centerY + y2 * perspective * scale;

        row.push({x: px, y: py, z: z2});
      }
      points.push(row);
    }

    // 绘制线框 (简化版，仅绘制主要网格)
    for (let i = 0; i <= gridSize; i+=2) {
      // 纵向线
      ctx.beginPath();
      for (let j = 0; j <= gridSize; j++) {
        const p = points[i][j];
        if (j === 0) ctx.moveTo(p.x, p.y);
        else ctx.lineTo(p.x, p.y);
      }
      ctx.stroke();

      // 横向线
      ctx.beginPath();
      for (let j = 0; j <= gridSize; j++) {
        const p = points[j][i];
        if (j === 0) ctx.moveTo(p.x, p.y);
        else ctx.lineTo(p.x, p.y);
      }
      ctx.stroke();
    }

    // 绘制当前操作点高亮
    const currentC = calculateCapacity(w, snr) / 50;
    const cx_raw = w - 2500;
    const cy_raw = snr - 50;
    const cz_raw = currentC;

    const cosX = Math.cos(rotationX);
    const sinX = Math.sin(rotationX);
    const cosY = Math.cos(rotationY);
    const sinY = Math.sin(rotationY);

    const x1 = cx_raw * cosY - cz_raw * sinY;
    const z1 = cz_raw * cosY + cx_raw * sinY;
    const y2 = cy_raw * cosX - z1 * sinX;
    const z2 = z1 * cosX + cy_raw * sinX;

    const perspective = fov / (fov + z2 + 200);
    const px = centerX + x1 * perspective * scale;
    const py = centerY + y2 * perspective * scale;

    ctx.fillStyle = '#007acc';
    ctx.beginPath();
    ctx.arc(px, py, 6, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 2;
    ctx.stroke();
  }

  // 事件监听
  canvas.addEventListener('mousedown', (e) => {
    isDragging = true;
    lastMouseX = e.clientX;
    lastMouseY = e.clientY;
    canvas.style.cursor = 'grabbing';
  });

  window.addEventListener('mousemove', (e) => {
    if (!isDragging) return;
    const deltaX = e.clientX - lastMouseX;
    const deltaY = e.clientY - lastMouseY;

    rotationY += deltaX * 0.01;
    rotationX += deltaY * 0.01;

    // 限制 X 轴旋转角度，避免翻转
    rotationX = Math.max(-Math.PI/2, Math.min(Math.PI/2, rotationX));

    lastMouseX = e.clientX;
    lastMouseY = e.clientY;

    drawSurface();
  });

  window.addEventListener('mouseup', () => {
    isDragging = false;
    canvas.style.cursor = 'grab';
  });

  inputW.addEventListener('input', drawSurface);
  inputSNR.addEventListener('input', drawSurface);

  btnReset.addEventListener('click', () => {
    rotationX = 0.5;
    rotationY = 0.5;
    inputW.value = 1000;
    inputSNR.value = 10;
    drawSurface();
  });

  // 键盘辅助控制
  window.addEventListener('keydown', (e) => {
    const step = 0.1;
    switch(e.key) {
      case 'ArrowUp': rotationX += step; break;
      case 'ArrowDown': rotationX -= step; break;
      case 'ArrowLeft': rotationY -= step; break;
      case 'ArrowRight': rotationY += step; break;
      default: return;
    }
    rotationX = Math.max(-Math.PI/2, Math.min(Math.PI/2, rotationX));
    drawSurface();
  });

  // 初始化
  drawSurface();
})();
